namespace App\Nova\Actions;

use Laravel\Nova\Actions\Action;
use Laravel\Nova\Fields\ActionFields;
use Illuminate\Support\Collection;
use App\Services\PatientExportService;
use Illuminate\Auth\Access\AuthorizationException;

class BulkExportPatientHistory extends Action
{
    public $name = 'Export Full Clinical History';

    public function handle(ActionFields $fields, Collection $models)
    {
        $user = auth()->user();
        foreach ($models as $patient) {
            if (!$user->can('exportMedicalHistory', $patient)) {
                return Action::danger("Unauthorized export attempt for patient ID {$patient->id}.");
            }
        }

        $service = app(PatientExportService::class);
        $archiveUrl = $service->generateEncryptedZip($models);

        return Action::download($archiveUrl, 'patient_records.zip');
    }
}
